          ..write('payload: $payload, ')
          ..write('outcome: $outcome, ')
          ..write('reasonCode: $reasonCode, ')
          ..write('errorMessage: $errorMessage, ')
          ..write('dependsOnMutationId: $dependsOnMutationId, ')
          ..write('rowid: $rowid')
          ..write(')'))
        .toString();
  }
}

